"""Build the self-contained, local HTML research report from research-data.json."""
from pathlib import Path
import json
import re

HERE = Path(__file__).resolve().parent

def build():
    data = json.loads((HERE / 'research-data.json').read_text())
    workspace_source = HERE / 'src' / 'workspace.html'
    workspace = (workspace_source if workspace_source.exists() else HERE / 'index.html').read_text()
    shared_style = re.search(r'<style>(.*?)</style>', workspace, re.S)[1].rstrip()
    payload = json.dumps(data, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c')
    template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><meta name="description" content="Source-backed research and a decision checkpoint for the Germany-first student product."><title>Student product · Research</title><link rel="icon" href="data:,"><style>__SHARED_STYLE__
.report-kicker { color:var(--soft); font-size:11px; margin-bottom:20px; }
.report-strip { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);margin:28px 0; }
.report-strip>div { padding:20px 18px;border-left:1px solid var(--rule); }.report-strip>div:first-child {padding-left:0;border-left:0;}
.report-strip b {display:block;font:normal 27px var(--display);letter-spacing:-.5px;}.report-strip span {font-size:11px;color:var(--soft);display:block;}.report-strip small {display:block;font-size:10px;color:var(--soft);margin-top:5px;}
.report-point {padding:20px 0;border-bottom:1px solid var(--rule);}.report-point h3 {font:normal 24px var(--display);margin:7px 0 10px;}.report-point p {font-size:13px;color:var(--soft);margin:0 0 10px;}
.evidence-list {display:grid;gap:0;margin-top:28px;}.evidence {padding:25px 0;border-top:1px solid var(--rule);}.evidence:last-child {border-bottom:1px solid var(--rule);}.evidence,.report-point {min-width:0;}.evidence .pill {white-space:normal;max-width:100%;}.evidence .meta {display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:10px;color:var(--soft);margin-bottom:12px;}.evidence h3 {font-size:15px;font-weight:550;line-height:1.65;}.evidence p {font-size:12px;color:var(--soft);margin:9px 0;}.evidence details {font-size:12px;color:var(--soft);margin-top:12px;}.evidence summary {cursor:pointer;text-decoration:underline;text-underline-offset:4px;}.evidence ul {padding-left:18px;}.evidence li {margin:8px 0;}
.source-links {display:flex;gap:10px 17px;flex-wrap:wrap;margin:12px 0 0;}.source-links a {font-size:11px;color:var(--brand);}.claim-refs {display:flex;gap:8px;flex-wrap:wrap;}.claim-ref {font-size:10px;color:var(--brand);text-decoration:none;}.claim-ref:hover {text-decoration:underline;}.research-note {border-left:2px solid var(--brand);padding:14px 18px;font-size:12px;background:var(--tint);margin:25px 0;}.section-label {font-size:10px;color:var(--soft);text-transform:uppercase;letter-spacing:1px;margin-top:30px;}.shortlist {padding-left:18px;font-size:13px;color:var(--soft);}.shortlist li {padding:7px 0;}.source-index {list-style:none;padding:0;margin:20px 0;}.source-index li {padding:13px 0;border-top:1px solid var(--rule);font-size:11px;color:var(--soft);overflow-wrap:anywhere;}.source-index a {display:block;font-size:12px;color:var(--ink);}.confidence-wrap {overflow-x:auto;}.confidence-table td:first-child {min-width:150px;}.confidence-table td {font-size:11px;}.gate-status {display:inline-flex;gap:8px;align-items:center;background:#efe4cb;color:#745414;padding:6px 11px;border-radius:3px;font-size:10px;text-transform:uppercase;letter-spacing:1px;font-weight:650;}.gate-columns {display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:30px;}.gate-columns h3 {font:normal 25px var(--display);}.gate-columns ul {padding-left:17px;color:var(--soft);font-size:12px;}.gate-columns li {margin:10px 0;}.gate-condition {display:grid;grid-template-columns:30px 1fr;gap:13px;padding:18px 0;border-top:1px solid var(--rule);}.gate-condition .n {font:italic 23px var(--display);color:var(--brand);}.gate-condition h3 {font-size:13px;margin:0 0 7px;}.gate-condition p {font-size:12px;color:var(--soft);margin:0;}.verification {border-top:1px solid var(--rule);margin-top:32px;padding-top:23px;font-size:12px;color:var(--soft);}.report-toplink {font-size:11px;color:var(--soft);text-decoration:none;}.report-controls {display:flex;gap:13px;align-items:center;flex-wrap:wrap;}.research-table-note {font-size:10px;color:var(--soft);margin:13px 0;}.competitor-table th,.competitor-table td {min-width:130px;}.competitor-table td:first-child {min-width:150px;}.competitor-table td {font-size:11px;}.competitor-table a {color:var(--brand);}.source-authority {font-size:11px;color:var(--soft);}
@media(max-width:650px){.gate-columns{grid-template-columns:1fr;gap:15px;}.report-strip{grid-template-columns:1fr;}.report-strip>div{padding:15px 0;border-left:0;border-bottom:1px solid var(--rule);}.report-strip>div:last-child{border-bottom:0;}.report-strip b{font-size:25px;}.report-controls{gap:8px;}.topbar{align-items:center;}.report-toplink{font-size:10px;}}
</style></head><body><a class="skip" href="#report-main">Skip to content</a><div class="shell"><aside class="sidebar" aria-label="Research navigation"><div class="wordmark"><svg class="mark" viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M6 29V7h23M7 28 29 7M17 28h12V16" stroke="currentColor" stroke-width="1.8"/></svg>Fieldnotes <span class="tiny" style="font-size:8px;color:var(--soft)">/ Research</span></div><p class="sidebar-label tiny">Student product</p><nav id="report-nav" aria-label="Research sections"></nav><div class="sidebar-foot"><span class="version"><span class="dot"></span>Germany-first research</span><p>Public-source evidence, estimates,<br>and the unknowns to test.</p><a class="quiet" href="index.html#plan">Back to the workspace ↗</a></div></aside><main class="main" id="report-main" tabindex="-1"><header class="topbar"><div class="crumb">Research<span>/</span><b id="crumb-current">Overview</b></div><div class="report-controls"><a class="report-toplink" href="index.html#plan">← Workspace</a><button class="btn" id="print-report" type="button">Print / save PDF</button></div></header><div id="report-views"></div><footer class="footer"><span id="report-date"></span><span>Public research ≠ customer validation</span></footer></main></div><script id="research-data" type="application/json">__RESEARCH_DATA__</script><script>
(()=>{
'use strict';
const data=JSON.parse(document.getElementById('research-data').textContent);
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>/^https?:\/\//.test(u)||/^(?:\.\.\/|index\.html|research-data\.json)/.test(u)?u:'#';
const claims=new Map(data.claims.map(c=>[c.id,c]));
const sourceLinks=sources=>'<div class="source-links">'+sources.map(s=>'<a href="'+esc(safeURL(s.url))+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a>').join('')+'</div>';
const refs=ids=>'<div class="claim-refs">'+(ids||[]).map(id=>'<a class="claim-ref" href="#claim-'+esc(id)+'">['+esc(id)+']</a>').join('')+'</div>';
const list=items=>'<ul class="shortlist">'+items.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
const label=(text,neutral=true)=>'<span class="pill '+(neutral?'pill-neutral':'')+'">'+esc(text)+'</span>';
function claim(c){return '<article class="evidence" id="claim-'+esc(c.id)+'"><div class="meta">'+label(c.label)+' '+label(c.confidence+' confidence')+'<span>'+esc(c.id)+' · '+esc(c.sourceDate||data.asOf)+'</span></div><h3>'+esc(c.claim)+'</h3><p><b>Implication:</b> '+esc(c.implication)+'</p>'+sourceLinks(c.sources||[])+'<details><summary>Evidence scope &amp; limits</summary><p>'+esc(c.limitations||'Read the source in context. This fact does not establish demand for our product.')+'</p><ul>'+(c.sources||[]).map(s=>'<li>'+esc(s.publisher||s.title)+' · '+esc(s.date||'Page checked '+data.asOf)+' · '+esc(s.authority||'See source methodology')+'</li>').join('')+'</ul></details></article>';}
function head(kicker,title,intro){return '<div class="eyebrow tiny"><span class="line"></span>'+esc(kicker)+'</div><h1>'+esc(title)+'</h1><p class="intro">'+esc(intro)+'</p>';}
const sectionNames=[['overview','Research overview'],...data.sections.map(s=>[s.id,s.navTitle||s.title]),['confidence','Evidence & gaps'],['gate','Research gate']];
$('#report-nav').innerHTML=sectionNames.map(([id,name],i)=>'<a class="nav-link" href="#'+id+'" data-route="'+id+'">'+esc(name)+'<span class="nav-no">0'+(i+1)+'</span></a>').join('');
let views='<section class="view" id="view-overview">'+head('Startup Design / Phase 3',data.title,data.subtitle)+'<span class="gate-status">'+esc(data.gate.status)+'</span><div class="report-strip">'+data.metrics.map(m=>'<div><b>'+esc(m.value)+'</b><span>'+esc(m.label)+'</span><small>'+esc(m.scope)+'</small>'+refs(m.claimIds)+'</div>').join('')+'</div>'+data.summary.map(p=>'<article class="report-point"><span class="tiny" style="color:var(--soft)">'+esc(p.label)+'</span><h3>'+esc(p.title)+'</h3><p>'+esc(p.text)+'</p>'+refs(p.claimIds)+'</article>').join('')+'<div class="section-head"><h2>The next decision</h2></div><p class="section-deck">'+esc(data.gate.recommendation)+'</p><a class="btn btn-primary" href="#gate">Read the research gate →</a></section>';
for(const section of data.sections){views+='<section class="view" id="view-'+esc(section.id)+'" hidden>'+head(section.kicker,section.title,section.intro);if(section.id==='alternatives'&&data.competitors?.length){views+='<div class="plan-table-wrap"><table class="plan-table competitor-table"><caption class="tiny" style="text-align:left;margin:10px 0;color:var(--soft)">Observed product positioning · '+esc(data.asOf)+'</caption><thead><tr><th>Alternative</th><th>Product / target</th><th>Price evidence</th><th>Strength</th><th>Limit / open question</th></tr></thead><tbody>'+data.competitors.map(c=>'<tr><td><a href="'+esc(safeURL(c.url))+'" target="_blank" rel="noopener">'+esc(c.name)+' ↗</a></td><td>'+esc(c.product)+'</td><td>'+esc(c.pricing)+'</td><td>'+esc(c.strength)+'</td><td>'+esc(c.limitation)+'</td></tr>').join('')+'</tbody></table></div><p class="research-table-note">Vendor features and prices are vendor-sourced observations, not independent proof of accuracy or student outcomes. Funding and traction are not assumed when unavailable.</p>';}
if(section.id==='students'){
 views+='<div class="plan-table-wrap"><table class="plan-table"><caption class="tiny" style="text-align:left;margin-bottom:10px;color:var(--soft)">Proposed interview cells — not validated personas</caption><thead><tr><th>Study intention</th><th>Exploring</th><th>Checking a plan</th></tr></thead><tbody><tr><td>Bachelor’s</td><td>Which entrance or preparation route could make sense?</td><td>What needs checking about the intended route or programme?</td></tr><tr><td>Master’s</td><td>Which study direction fits the prior degree and goals?</td><td>Which programme requirements or cost assumptions are unresolved?</td></tr></tbody></table></div>';
 if(data.studentQuotes?.length)views+='<div class="section-head"><h2>Language from public accounts</h2></div><p class="section-deck">Self-selected anecdotes, not customer interviews or testimonials for this product.</p>'+data.studentQuotes.map(q=>'<blockquote class="report-point" style="margin:0"><p style="font-family:var(--display);font-size:21px;color:var(--ink)">“'+esc(q.quote)+'”</p><p>'+esc(q.context)+' · '+esc(q.date)+'</p><p>'+esc(q.limitations)+'</p><a class="text-link" target="_blank" rel="noopener" href="'+esc(safeURL(q.url))+'">Read the public account ↗</a></blockquote>').join('');
}
views+='<p class="source-authority">Overall confidence: '+esc(section.confidence||'See claim-level ratings')+'</p><div class="evidence-list">'+section.claimIds.map(id=>claims.has(id)?claim(claims.get(id)):'').join('')+'</div><div class="section-head"><h2>What this means for the product</h2></div>'+list(section.implications)+'<div class="section-head"><h2>Data gaps</h2></div>'+list(section.gaps)+((section.connections||[]).length?'<p class="section-label">Related evidence</p>'+refs(section.connections):'')+'<div class="research-note"><b>Red flags:</b> '+esc(section.redFlags||section.flags||'See gate conditions')+'<br><b>Yellow flags:</b> '+esc(section.yellowFlags||'See declared data gaps')+'</div></section>';}
const sources=[...new Map([...data.claims.flatMap(c=>c.sources||[]),...(data.competitors||[]).flatMap(c=>c.sources||[])].map(s=>[s.url,s])).values()];
views+='<section class="view" id="view-confidence" hidden>'+head('Phase 3 / Confidence assessment','Know where the evidence stops.','Source authority and representativeness are separate. A reliable count or rule does not validate a business model.')+'<div class="confidence-wrap"><table class="plan-table confidence-table"><thead><tr><th>Claim</th><th>Type</th><th>Confidence</th><th>Evidence date</th><th>Scope</th></tr></thead><tbody>'+data.claims.map(c=>'<tr><td><a href="#claim-'+esc(c.id)+'">'+esc(c.id)+' · '+esc(c.shortTitle||c.claim.slice(0,70))+'</a></td><td>'+esc(c.label)+'</td><td>'+esc(c.confidence)+'</td><td>'+esc(c.sourceDate||data.asOf)+'</td><td>'+esc(c.scopeNote||'See full claim scope')+'</td></tr>').join('')+'</tbody></table></div><div class="section-head"><h2>Critical unknowns</h2></div>'+list(data.criticalUnknowns)+'<div class="section-head"><h2>Verification</h2></div><div class="verification" id="verification-summary">'+esc(data.verification.summary)+list(data.verification.notes||[])+'</div><div class="section-head"><h2>Source index</h2></div><ol class="source-index">'+sources.map(s=>'<li><a href="'+esc(safeURL(s.url))+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a>'+esc(s.publisher||'')+' · '+esc(s.date||'Checked '+data.asOf)+'</li>').join('')+'</ol></section>';
views+='<section class="view" id="view-gate" hidden>'+head('Startup Design / Phase 3.5','Choose the next investment.',data.gate.intro)+'<span class="gate-status">'+esc(data.gate.status)+'</span><div class="plan-callout"><h3>'+esc(data.gate.heading)+'</h3><p>'+esc(data.gate.recommendation)+'</p></div><div class="gate-columns"><div><h3>What supports continuing</h3>'+list(data.gate.for)+'</div><div><h3>What remains unproven</h3>'+list(data.gate.against)+'</div></div><div class="section-head"><h2>Conditions for the next step</h2></div><p class="section-deck">These are proposed experiment criteria [Planning judgment], not observed results or statistical proof.</p>'+data.gate.conditions.map((c,i)=>'<div class="gate-condition"><span class="n">0'+(i+1)+'</span><div><h3>'+esc(c.title)+'</h3><p>'+esc(c.test)+'</p></div></div>').join('')+'<div class="section-head"><h2>Continue, adjust, or stop</h2></div>'+list(data.gate.choices)+'<div class="research-note">'+esc(data.gate.skillCheckpoint)+'</div>'+refs(data.gate.claimIds)+'<div class="section-head"><h2>Red &amp; yellow flags</h2></div>'+list(data.gate.flags)+'</section>';
$('#report-views').innerHTML=views;$('#report-date').textContent='Research checked '+data.asOf+' · Source dates vary';
function navigate(focus=false){const raw=location.hash.slice(1)||'overview';let id=sectionNames.some(([k])=>k===raw)?raw:'overview';let target=null;if(raw.startsWith('claim-')){target=document.getElementById(raw);const parent=target?.closest('.view');if(parent)id=parent.id.slice(5);}$$('.view').forEach(v=>v.hidden=v.id!=='view-'+id);$$('.nav-link').forEach(a=>{if(a.dataset.route===id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#crumb-current').textContent=sectionNames.find(([k])=>k===id)[1];document.title=$('#crumb-current').textContent+' · Student research';if(focus){$('#report-main').focus({preventScroll:true});if(target)target.scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo({top:0,behavior:'instant'});}}
window.addEventListener('hashchange',()=>navigate(true));navigate();$('#print-report').addEventListener('click',()=>window.print());
})();
</script></body></html>'''
    output = template.replace('__SHARED_STYLE__', shared_style).replace('__RESEARCH_DATA__', payload)
    (HERE / 'research.html').write_text(output)
    print(f'Built research.html with {len(data["claims"])} curated claims.')

if __name__ == '__main__':
    build()
